/**
 * Emoji picker: search, a tab per group (the site's reactions first, then the
 * Unicode groups) and a grid. Used by reactions in UNA's "Many" mode; the data
 * is generated by scripts/generate-emoji-data.js.
 */

import { useState } from 'react';
import { useTranslation } from 'react-i18next';
import { View, Pressable, ScrollView, Row } from 'app/design/view';
import { Text } from 'app/design/typography';
import { InputWithIcons } from 'app/design/controls';
import { cn, isWeb } from 'app/lib/util';
import { EMOJI_GROUPS, type EmojiEntry } from 'app/lib/emoji/emoji-data';
import { emojiKey } from 'app/lib/emoji/reaction-emoji';

export type EmojiPickerItem = {
    emoji: string;
    title: string;
};

export type EmojiPickerProps = {
    onSelect: (emoji: string) => void;
    /** Emoji to show as chosen (the viewer's reactions). */
    selected?: readonly string[];
    /** Emoji that can't be chosen right now (e.g. the reactions limit is reached). */
    isDisabled?: (emoji: string) => boolean;
    /** Shown first, in their own tab: the site's reactions list. */
    quick?: readonly EmojiPickerItem[];
    /** A line under the grid, e.g. the reactions limit. */
    note?: string;
    className?: string;
};

const QUICK_TAB = 'quick';
const SEARCH_LIMIT = 120;

function searchEmoji(query: string): EmojiEntry[] {
    const words = query.toLowerCase().split(/\s+/).filter(Boolean);
    const found: EmojiEntry[] = [];
    for (const group of EMOJI_GROUPS) {
        for (const entry of group.emojis) {
            if (words.every((word) => entry[1].includes(word))) found.push(entry);
            if (found.length >= SEARCH_LIMIT) return found;
        }
    }
    return found;
}

export default function EmojiPicker({
    onSelect,
    selected = [],
    isDisabled,
    quick = [],
    note,
    className,
}: EmojiPickerProps) {
    const { t } = useTranslation();
    const [query, setQuery] = useState('');
    const [tab, setTab] = useState<string>(quick.length ? QUICK_TAB : (EMOJI_GROUPS[0]?.id ?? ''));

    const selectedKeys = new Set(selected.map(emojiKey));
    const search = query.trim();

    let entries: readonly EmojiEntry[];
    if (search) entries = searchEmoji(search);
    else if (tab === QUICK_TAB) entries = quick.map((item) => [item.emoji, item.title] as const);
    else entries = EMOJI_GROUPS.find((group) => group.id === tab)?.emojis ?? [];

    const tabs = [
        ...(quick.length && quick[0] ? [{ id: QUICK_TAB, title: t('Reactions'), icon: quick[0].emoji }] : []),
        ...EMOJI_GROUPS.map((group) => ({ id: group.id, title: t(group.title), icon: group.emojis[0]?.[0] ?? '' })),
    ];

    return (
        <View className={cn('w-full gap-2', className)}>
            <InputWithIcons
                size="small"
                rounded="full"
                startDecorator="Search"
                placeholder={t('Search emoji')}
                aria-label={t('Search emoji')}
                role="searchbox"
                autoCapitalize="none"
                autoCorrect={false}
                value={query}
                onChangeText={setQuery}
            />

            {/* The tabs stay while searching, so the picker keeps its size; a tab ends the search. */}
            <Row className="justify-between" role="tablist">
                {tabs.map((item) => {
                    const active = !search && item.id === tab;
                    return (
                        <Pressable
                            key={item.id}
                            role="tab"
                            aria-selected={active}
                            accessibilityLabel={item.title}
                            onPress={() => {
                                setQuery('');
                                setTab(item.id);
                            }}
                            className={cn(
                                'w-8 h-8 items-center justify-center rounded-lg web:hover:bg-muted/60',
                                active && 'bg-muted'
                            )}
                        >
                            <Text className={cn('text-lg', !active && 'opacity-60')}>{item.icon}</Text>
                        </Pressable>
                    );
                })}
            </Row>

            <ScrollView
                className="h-60"
                contentContainerClassName="flex-row flex-wrap"
                // One tap picks an emoji while the search keyboard is open.
                keyboardShouldPersistTaps="handled"
            >
                {entries.map(([emoji, name]) => {
                    const chosen = selectedKeys.has(emojiKey(emoji));
                    const disabled = !chosen && !!isDisabled?.(emoji);
                    return (
                        <Pressable
                            key={emoji}
                            accessibilityRole="button"
                            accessibilityLabel={name}
                            accessibilityState={{ selected: chosen, disabled }}
                            // Web drops accessibilityState: say which emoji are chosen, as toggles.
                            {...(isWeb ? { 'aria-pressed': chosen, 'aria-disabled': disabled } : {})}
                            disabled={disabled}
                            onPress={() => onSelect(emoji)}
                            className={cn(
                                'w-10 h-10 items-center justify-center rounded-lg',
                                chosen ? 'bg-accent' : 'web:hover:bg-muted/60 web:active:bg-muted',
                                disabled && 'opacity-40'
                            )}
                        >
                            <Text className="text-2xl">{emoji}</Text>
                        </Pressable>
                    );
                })}
                {!entries.length ? (
                    <Text className="w-full py-6 text-center text-sm text-muted-foreground">
                        {t('No emoji found')}
                    </Text>
                ) : null}
            </ScrollView>

            {note ? <Text className="text-xs text-muted-foreground">{note}</Text> : null}
        </View>
    );
}
